const noop = () => {}
const noopRefresh = () => {}
// The system bar in a headset: up ahead, where the settings panel hung. Its
// panels (settings, inventory) open under it.
const XR_BAR_ELEVATION = 66
/** Flat, where a panel opened from the system bar starts: under the bar. */
const UNDER_BAR = 8 + BAR_HEIGHT + 8
const XR_BAR_DISTANCE = 1.4

/*
A SYSTEM PANEL'S FIRST SEAT IN A HEADSET, from where it is pinned flat. A
panel pinned to the left edge goes left of centre and one pinned right goes
right (left of centre is negative azimuth, as `left-shoulder` is), its inner
edge a little off the middle; a pixel `top` below the bar puts it that much
lower, at the scale the panel is drawn (K metres per viewBox unit). Unpinned,
it is under the bar, centred. So an app's two columns stay two columns.
*/
function xrSeatFor(
  pin: ScreenAnchor | undefined,
  width: number,
  halfHeightDeg: number,
  K: number
): { azimuthDeg: number; elevationDeg: number; distance: number } {
  const deg = (m: number) => (Math.atan2(m, XR_BAR_DISTANCE) * 180) / Math.PI
  const side =
    pin?.left != null && pin.right == null
      ? -1
      : pin?.right != null && pin.left == null
      ? 1
      : 0
  const down =
    typeof pin?.top === 'number' ? Math.max(0, pin.top - UNDER_BAR) * K : 0
  return {
    azimuthDeg: side * (8 + deg(width / 2)),
    elevationDeg: XR_BAR_ELEVATION - 5 - halfHeightDeg - deg(down),
    distance: XR_BAR_DISTANCE,
  }
}

/** A registered fog contributor: underwater, cloud, space… (see atmosphere.ts). */
type FogContributor = () => FogLayer | null

/** One debug source's live <text> nodes, so the panel can update without rebuilding. */
/** What `panel3d` hangs on its root for one-call popups — see widgets3d. */
type PanelPopup = (
  config: { title?: string; width?: number; handleClose?: () => void },
  ...items: Widget3d[]
) => { close: () => void }

type LiveDebugRow = {
  /** Push the source's current lines into its text block (re-wraps at the last width). */
  update: (lines: string[]) => void
  lines: () => string[]
}

// Read-only local axes reused by the per-frame XR loops (getDirectionToRef
// reads but never mutates them), so we never allocate a Vector3 per frame.
const XR_FORWARD = new BABYLON.Vector3(0, 0, 1)
const XR_RIGHT = new BABYLON.Vector3(1, 0, 0)

/*
WHICHEVER HAND YOU PRESS WITH, THE PRESS COUNTS.

Babylon points with ONE controller at a time. A press on the other one only
switches the pointer to it, and the press itself is dropped. A Quest decides for
itself which controller is active, so in practice a press now and then did
nothing, and a player just learns that the pointer is flaky (Tonio: "I think I
and most users just internalize flaky pointer behavior"). Nobody should have
to know which hand is "active".

So: a press on a controller that is not pointing switches to it AND is
delivered, once its ray has picked something (on the next frame or two).
Babylon's own release pairs with it, because by then that controller is the one
pointing. This reads Babylon's per-controller state (`_controllers`, `pick`,
`pointerDownTriggered`), which is private. `xr-press.test.ts` pins those names
and the drop itself, so a Babylon upgrade that renames them (or fixes the drop)
fails the suite and says which; in a live session it warns once instead.
*/
function pressWithEitherHand(
  xr: BABYLON.WebXRDefaultExperience,
  scene: BABYLON.Scene
): void {
  const sel = xr.pointerSelection as any
  const frames = xr.baseExperience?.sessionManager.onXRFrameObservable
  // Pinned by xr-press.test.ts; this is the same check, live, so a Babylon
  // that changed under us says so instead of quietly dropping presses again.
  if (
    sel?._controllers == null ||
    typeof sel.setAttachedController !== 'function'
  ) {
    console.warn(
      'tosi-b3d: Babylon XR pointer selection has changed (no _controllers / setAttachedController), so a press on the hand that is not pointing is dropped again. See pressWithEitherHand.'
    )
    return
  }
  xr.input.onControllerAddedObservable.add((controller) => {
    const watch = (mc: BABYLON.WebXRAbstractMotionController) => {
      const main = mc.getMainComponent()
      if (main == null || frames == null) return
      main.onButtonStateChangedObservable.add(
        (c) => {
          if (!c.changes.pressed?.current) return
          const id = controller.uniqueId
          if (
            sel._attachedController === id ||
            !sel.setAttachedController?.(id)
          )
            return
          let tries = 0
          const obs = frames.add(() => {
            const data = sel._controllers?.[id]
            if (data?.pick || ++tries > 5) frames.remove(obs)
            if (!data?.pick) return
            const init = { pointerId: data.id, pointerType: 'xr' }
            scene.simulatePointerDown(data.pick, init)
            data.pointerDownTriggered = true
            // Let go already? Then it was a tap.
            if (!main.pressed) scene.simulatePointerUp(data.pick, init)
          })
        },
        undefined,
        true // ahead of Babylon's own observer, which drops it
      )
    }
    if (controller.motionController) watch(controller.motionController)
    else controller.onMotionControllerInitObservable.addOnce(watch)
  })
}

/*
A CONTROLLER RAY PICKS THE UI LAYERS FIRST.

Babylon's XR pointer selection picks the world and its own default utility
layer, and a nearer world hit wins: so a `ui`/`modal` panel, drawn over the
world, was out of reach in a headset (a wall in between took the ray; and our
layers were never asked at all). While Babylon's rays are being picked (from
the start of an XR frame to the scene's render), a ray that hits one of our
layers returns THAT pick, so it beats the world and the laser stops at the
panel. The pick's distance is lengthened a centimetre because Babylon cuts its
ray to the hit distance and the press re-casts it (an exact-length ray can
fall just short of the plane). Other picks (a biped's ground probe, in
onBeforeRender) are outside the window and untouched.
*/
function pickLayersFirst(
  xr: BABYLON.WebXRDefaultExperience,
  scene: BABYLON.Scene
): () => void {
  const frames = xr.baseExperience?.sessionManager.onXRFrameObservable
  if (frames == null) return () => {}
  const own = Object.prototype.hasOwnProperty.call(scene, 'pickWithRay')
  const original = scene.pickWithRay
  let picking = false
  const start = frames.add(() => (picking = true), undefined, true)
  const end = scene.onBeforeRenderObservable.add(() => (picking = false))
  scene.pickWithRay = function (ray, predicate, fastCheck, trianglePredicate) {
    if (picking) {
      const hit = pickPanelLayers(scene, ray)
      if (hit) {
        hit.distance += 0.01
        return hit
      }
    }
    return original.call(scene, ray, predicate, fastCheck, trianglePredicate)
  }
  return () => {
    frames.remove(start)
    scene.onBeforeRenderObservable.remove(end)
    if (own) scene.pickWithRay = original
    else delete (scene as any).pickWithRay
  }
}

/*
A REBUILT PANEL KEEPS ITS PLACE. The settings panel is rebuilt on every icon
press and refresh (a new element: its rows' closures cannot be reused), and
each rebuild started back at the top, so pressing a toggle at the bottom of a
long panel threw you to the top of it. The new panel is scrolled to where the
old one was (clamped, if it is shorter).
*/
function carryScroll(from: Element | null, to: SVGSVGElement): void {
  const top = (from as { scrollTop?: number } | null)?.scrollTop ?? 0
  if (top > 0 && 'scrollTop' in to)
    (to as { scrollTop: number }).scrollTop = top
}

